with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الهيدرومeteorولوجيا والموارد المائية والتنبؤ الهيدرولوجي','قياس المطر والتبخر والنتح ورطوبة التربة ونمذجة الأحواض والجريان والفيضانات والتنبؤ المائي وإدارة الموارد.',34,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'عمليات المطر والجريان والأحواض',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التنبؤ المائي وإدارة الموارد',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('hydrometeorology-water-cycle-linkages','العلاقات بين الأرصاد والهيدرولوجيا','ربط المطر والتبخر والنتح والتخزين والجريان ضمن دورة الماء.','{"blocks":[{"type":"text","text":"يشرح الدرس العلاقات بين الأرصاد والهيدرولوجيا ضمن الترابط بين الغلاف الجوي وسطح الأرض والموارد المائية."},{"type":"text","text":"المفهوم المحوري: ربط المطر والتبخر والنتح والتخزين والجريان ضمن دورة الماء.، ويعتمد التحليل على تحديد المقياس المكاني والزمني المناسب."},{"type":"text","text":"تجمع البيانات من المحطات المطرية والهيدرولوجية والمنتجات الفضائية والنماذج مع توثيق المصدر والدقة."},{"type":"text","text":"تراجع جودة السجلات واكتمالها وتجانسها قبل استخدامها في الحساب أو المعايرة."},{"type":"text","text":"تحدد خصائص الحوض أو النظام المائي المؤثرة مثل المساحة والانحدار والتربة والغطاء الأرضي وشبكة التصريف."},{"type":"text","text":"تفصل المدخلات الجوية عن خصائص النظام الأرضي حتى يمكن تفسير أسباب الاختلاف في الاستجابة."},{"type":"text","text":"تختار الطريقة الحسابية أو النموذج وفق الهدف والبيانات المتاحة ومجال الصلاحية."},{"type":"text","text":"تعاير المعلمات باستخدام فترة مناسبة، ثم تختبر الأداء على فترة مستقلة كلما أمكن."},{"type":"text","text":"تستخدم مؤشرات متعددة لتقييم التحيز وتوقيت الذروة وحجم التدفق واستمرارية التمثيل."},{"type":"text","text":"توضح النتائج كنطاقات عندما يكون عدم اليقين في التوقع المطري أو خصائص الحوض مؤثراً."},{"type":"text","text":"مثال تطبيقي: مقارنة استجابة حوض قبل وبعد حدث مطري مع توثيق المطر المساحي والتدفق المرصود وحالة التربة السابقة."},{"type":"callout","text":"الخلاصة: التحليل الهيدرولوجي الموثوق يربط الرصد الجوي بخصائص الحوض والقياسات المائية والتحقق المستقل."}]}',3160,60,'["شرح العملية الهيدرومeteorولوجية","اختيار البيانات والطريقة المناسبة","تقييم النتائج وعدم اليقين"]','عمليات المطر والجريان والأحواض'),
('precipitation-measurement-networks','شبكات قياس الهطول المطري','المقاييس التقليدية والآلية والرادارية وتوزيع المحطات.','{"blocks":[{"type":"text","text":"يشرح الدرس شبكات قياس الهطول المطري ضمن الترابط بين الغلاف الجوي وسطح الأرض والموارد المائية."},{"type":"text","text":"المفهوم المحوري: المقاييس التقليدية والآلية والرادارية وتوزيع المحطات.، ويعتمد التحليل على تحديد المقياس المكاني والزمني المناسب."},{"type":"text","text":"تجمع البيانات من المحطات المطرية والهيدرولوجية والمنتجات الفضائية والنماذج مع توثيق المصدر والدقة."},{"type":"text","text":"تراجع جودة السجلات واكتمالها وتجانسها قبل استخدامها في الحساب أو المعايرة."},{"type":"text","text":"تحدد خصائص الحوض أو النظام المائي المؤثرة مثل المساحة والانحدار والتربة والغطاء الأرضي وشبكة التصريف."},{"type":"text","text":"تفصل المدخلات الجوية عن خصائص النظام الأرضي حتى يمكن تفسير أسباب الاختلاف في الاستجابة."},{"type":"text","text":"تختار الطريقة الحسابية أو النموذج وفق الهدف والبيانات المتاحة ومجال الصلاحية."},{"type":"text","text":"تعاير المعلمات باستخدام فترة مناسبة، ثم تختبر الأداء على فترة مستقلة كلما أمكن."},{"type":"text","text":"تستخدم مؤشرات متعددة لتقييم التحيز وتوقيت الذروة وحجم التدفق واستمرارية التمثيل."},{"type":"text","text":"توضح النتائج كنطاقات عندما يكون عدم اليقين في التوقع المطري أو خصائص الحوض مؤثراً."},{"type":"text","text":"مثال تطبيقي: مقارنة استجابة حوض قبل وبعد حدث مطري مع توثيق المطر المساحي والتدفق المرصود وحالة التربة السابقة."},{"type":"callout","text":"الخلاصة: التحليل الهيدرولوجي الموثوق يربط الرصد الجوي بخصائص الحوض والقياسات المائية والتحقق المستقل."}]}',3170,60,'["شرح العملية الهيدرومeteorولوجية","اختيار البيانات والطريقة المناسبة","تقييم النتائج وعدم اليقين"]','عمليات المطر والجريان والأحواض'),
