('integrated-basin-water-planning','التخطيط المتكامل للموارد المائية على مستوى الحوض','ربط المناخ والمياه والطلب والتشغيل والبيئة.','{"blocks":[{"type":"text","text":"يشرح الدرس التخطيط المتكامل للموارد المائية على مستوى الحوض ضمن الترابط بين الغلاف الجوي وسطح الأرض والموارد المائية."},{"type":"text","text":"المفهوم المحوري: ربط المناخ والمياه والطلب والتشغيل والبيئة.، ويعتمد التحليل على تحديد المقياس المكاني والزمني المناسب."},{"type":"text","text":"تجمع البيانات من المحطات المطرية والهيدرولوجية والمنتجات الفضائية والنماذج مع توثيق المصدر والدقة."},{"type":"text","text":"تراجع جودة السجلات واكتمالها وتجانسها قبل استخدامها في الحساب أو المعايرة."},{"type":"text","text":"تحدد خصائص الحوض أو النظام المائي المؤثرة مثل المساحة والانحدار والتربة والغطاء الأرضي وشبكة التصريف."},{"type":"text","text":"تفصل المدخلات الجوية عن خصائص النظام الأرضي حتى يمكن تفسير أسباب الاختلاف في الاستجابة."},{"type":"text","text":"تختار الطريقة الحسابية أو النموذج وفق الهدف والبيانات المتاحة ومجال الصلاحية."},{"type":"text","text":"تعاير المعلمات باستخدام فترة مناسبة، ثم تختبر الأداء على فترة مستقلة كلما أمكن."},{"type":"text","text":"تستخدم مؤشرات متعددة لتقييم التحيز وتوقيت الذروة وحجم التدفق واستمرارية التمثيل."},{"type":"text","text":"توضح النتائج كنطاقات عندما يكون عدم اليقين في التوقع المطري أو خصائص الحوض مؤثراً."},{"type":"text","text":"مثال تطبيقي: مقارنة استجابة حوض قبل وبعد حدث مطري مع توثيق المطر المساحي والتدفق المرصود وحالة التربة السابقة."},{"type":"callout","text":"الخلاصة: التحليل الهيدرولوجي الموثوق يربط الرصد الجوي بخصائص الحوض والقياسات المائية والتحقق المستقل."}]}',3350,60,'["شرح العملية الهيدرومeteorولوجية","اختيار البيانات والطريقة المناسبة","تقييم النتائج وعدم اليقين"]','التنبؤ المائي وإدارة الموارد'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'عمليات المطر والجريان والأحواض' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الهيدرومeteorولوجيا والموارد المائية والتنبؤ الهيدرولوجي',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;